import {renderModelLab} from './ml-view.js';
import {renderEvaluation} from './evaluation-view.js';
import {esc,fmt,money,shortDate,icon,folderArt,badge,metric,chart,bars,heatmap} from './ui.js';
const $=s=>document.querySelector(s);
const state={user:null,summary:null,history:null,forecast:null,plan:null,view:'home',tree:'sedes',expanded:new Set(['Paseo la Breña']),branch:'',product:'',horizon:7,temperature:'',rain:'',folderView:'grid',fileSearch:'',search:'',sort:'recent',day:'',renderId:0,dbTable:'sales',dbOffset:0,margin:.20,mlSeries:'',mlStep:0,mlDay:0,mlCache:null,mlPlaying:false};
const views={ml:'Cómo funciona la predicción',savings:'Ahorro potencial',database:'Base de datos',home:'Resumen',files:'Datos y archivos',forecast:'Predicciones',compare:'Comparar sedes',inventory:'Inventario',recipes:'Recetas estándar',plan:'Plan de preparación',evaluation:'Evaluación del modelo',events:'Eventos y clima'};
const api=async(path,options={})=>{
 const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...(options.body&&!(options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...options.headers}});
 if(!response.ok){let error;try{error=await response.json()}catch{error={detail:'No se pudo conectar con el servidor.'}};if(response.status===401&&state.user){state.user=null;renderLogin()}throw new Error(typeof error.detail==='string'?error.detail:'Revisa los campos: '+(error.detail||[]).map(e=>e.loc.at(-1)+' '+e.msg).join(', '))}
 return response.json();
};
const json=body=>JSON.stringify(body);
const toast=(message,error=false)=>{const root=$('#toast-root');root.innerHTML=`<div class="toast ${error?'error':''}" role="status">${esc(message)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>root.innerHTML='',5500)};
const note=(text,type='')=>`<div class="note-box ${type}">${icon('info')}<span>${esc(text)}</span></div>`;
const loading=text=>`<div class="loading"><div class="spinner"></div>${text||'Cargando tu espacio…'}</div>`;
const initials=name=>name.split(' ').slice(0,2).map(x=>x[0]).join('');
const query=()=>new URLSearchParams({horizon:state.horizon,...(state.temperature!==''?{temperature:state.temperature}:{}),...(state.rain!==''?{rain:state.rain}:{})});
const filtered=rows=>rows.filter(r=>(!state.branch||r.sede===state.branch)&&(!state.product||r.producto===state.product));
const branchOptions=(all=true)=>`${all?'<option value="">Todas las sedes</option>':''}${state.summary.sedes.map(s=>`<option ${state.branch===s.name?'selected':''} value="${esc(s.name)}">${esc(s.name)}</option>`).join('')}`;
const productOptions=()=>`<option value="">Todos los productos</option>${state.summary.products.map(p=>`<option ${state.product===p?'selected':''} value="${esc(p)}">${esc(p)}</option>`).join('')}`;
function modal(title,body,footer='',narrow=false){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button data-act="close-modal" aria-label="Cerrar">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;$('#modal-root button, #modal-root input, #modal-root select')?.focus()}
function renderLogin(){
 $('#app').innerHTML=`<main class="login-page"><section class="login-art"><div class="workspace-title"><div class="brand-mark"><img class="system-logo" src="/assets/atc-logo.png" alt="American Texas Chicken" width="128" height="128"></div><span style="margin-left:10px">American Texas Chicken</span></div><div><div class="eyebrow" style="margin-bottom:20px">Menos intuición. Más previsión.</div><h1>El próximo buen servicio empieza aquí.</h1><p>Ventas, insumos y preparación. Todas tus sedes, en un mismo lugar.</p>${folderArt()}</div><span class="muted small">Hecho para tu operación · Huancayo, Perú</span></section><section class="login-form-wrap"><form id="login-form" class="login-form"><img class="system-logo" src="/assets/atc-logo.png" alt="American Texas Chicken" width="128" height="128"><div class="eyebrow">Tu espacio de trabajo</div><h1>Qué bueno verte.</h1><p>Inicia sesión para planificar el siguiente servicio.</p><div id="login-error" class="form-error" role="alert"></div><div class="form-stack"><div><label class="field-label" for="email">Correo electrónico</label><input id="email" class="field" name="email" type="email" autocomplete="username" placeholder="nombre@americantexas.pe" required></div><div><label class="field-label" for="password">Contraseña</label><input id="password" class="field" name="password" type="password" autocomplete="current-password" placeholder="Tu contraseña" required></div><button class="button primary" type="submit">Ingresar al espacio ${icon('arrow')}</button></div><p style="font-size:10px;margin-top:22px">Acceso a la operación de American Texas Chicken. Usa tu cuenta de administrador o de sede.</p></form></section></main>`;
 $('#login-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);await signIn(data.get('email'),data.get('password'))};
}
async function signIn(email,password){const button=$('#login-form button[type="submit"]');if(button)button.disabled=true;try{state.user=await api('/login',{method:'POST',body:json({email,password})});await refresh();renderShell()}catch(e){const box=$('#login-error');if(box)box.textContent=e.message;else toast(e.message,true)}finally{if(button)button.disabled=false}}
async function refresh(){state.summary=await api('/summary');state.history=null;state.forecast=null;state.plan=null;state.mlCache=null}
function navButton(view,label,ico,count=''){return `<button class="nav-item ${state.view===view?'active':''}" data-view="${view}">${icon(ico)}<span>${label}</span>${count!==''?`<span class="nav-count">${count}</span>`:''}</button>`}
function treeHtml(){let search=state.search.toLowerCase();if(state.tree==='productos')return state.summary.products.filter(p=>p.toLowerCase().includes(search)).map((p,i)=>`<button class="tree-root" data-act="select-product" data-product="${esc(p)}">${icon('utensils')}<strong>${esc(p)}</strong><span class="nav-count">${state.summary.sedes.length}</span></button>`).join('');return state.summary.sedes.filter(s=>s.name.toLowerCase().includes(search)||state.summary.products.some(p=>p.toLowerCase().includes(search))).map(s=>`<button class="tree-root" data-act="tree-toggle" data-branch="${esc(s.name)}">${icon(state.expanded.has(s.name)?'down':'chevron','chevron')}${icon('folder')}<strong>${esc(s.name)}</strong><span class="nav-count">${s.files}</span></button>${state.expanded.has(s.name)?`<div class="tree-children">${state.summary.products.map(p=>`<button class="tree-child" data-act="select-series" data-branch="${esc(s.name)}" data-product="${esc(p)}">${icon('files')}${esc(p)}</button>`).join('')}<button class="tree-child" data-act="branch-files" data-branch="${esc(s.name)}">${icon('folder')}Archivos cargados <span class="nav-count">${s.files}</span></button></div>`:''}`).join('')}
function renderShell(){
 const u=state.user,s=state.summary;
 $('#app').innerHTML=`<div class="layout"><nav class="rail" aria-label="Navegación principal"><a class="brand-mark" href="#home" title="American Texas Chicken" aria-label="American Texas Chicken, inicio"><img class="system-logo" src="/assets/atc-logo.png" alt="American Texas Chicken" width="128" height="128"></a><div class="rail-nav">${[['home','home','Resumen'],['files','folder','Datos y archivos'],['compare','compare','Comparar sedes'],['forecast','chart','Predicciones']].map(([v,i,t])=>`<button class="rail-btn ${state.view===v?'active':''}" data-view="${v}" title="${t}" aria-label="${t}">${icon(i)}</button>`).join('')}</div><div class="rail-bottom"><button class="rail-btn" data-act="help" title="Ayuda" aria-label="Ayuda">${icon('help')}</button><button class="rail-btn" data-act="account" title="Mi cuenta" aria-label="Mi cuenta">${icon('settings')}</button><button class="avatar large" data-act="account" title="${esc(u.name)}">${initials(u.name)}</button></div></nav><aside class="side" id="sidebar"><div><div class="workspace-title"><img class="workspace-logo" src="/assets/atc-logo.png" alt="" width="36" height="36"><span>American Texas Chicken</span><button class="side-close" data-act="close-sidebar" aria-label="Cerrar menú">${icon('close')}</button></div><div class="workspace-sub">Espacio de trabajo</div></div><label class="side-search">${icon('search')}<input id="workspace-search" placeholder="Buscar en tu espacio" value="${esc(state.search)}" aria-label="Buscar sedes o productos"><span class="kbd">⌘ K</span></label><nav aria-label="Secciones">${navButton('home','Resumen','home')}${navButton('files','Datos y archivos','files',s.files.length)}${navButton('forecast','Predicciones','trend')}${navButton('plan','Plan de preparación','utensils')}${navButton('savings','Ahorro potencial','trend')}${navButton('ml','Cómo funciona la predicción','spark')}${navButton('inventory','Inventario','box')}${navButton('recipes','Recetas estándar','list')}${u.role==='admin'?navButton('database','Base de datos','building'):''}</nav><div class="side-section"><div class="side-label eyebrow"><span>Tu organización</span><button data-act="upload" title="Agregar archivo" aria-label="Agregar archivo">${icon('plus')}</button></div><div class="segmented"><button data-act="tree-tab" data-tab="sedes" class="${state.tree==='sedes'?'active':''}">Sedes</button><button data-act="tree-tab" data-tab="productos" class="${state.tree==='productos'?'active':''}">Productos</button></div><div class="tree" id="tree">${treeHtml()}</div></div><div class="side-footer"><button class="nav-item" data-view="events">${icon('calendar')}Eventos y clima</button><button class="nav-item" data-view="evaluation">${icon('shield')}Evaluación del modelo</button><div class="plan-card" style="margin-top:18px"><strong>${icon('spark')} Una cocina un paso adelante</strong><p>Convierte tus datos en el próximo buen servicio.</p><button data-view="forecast" class="row-button small">Ver predicciones ${icon('arrow')}</button></div><div class="location">${icon('pin')}Huancayo, Perú <span style="margin-left:auto">S/ · PEN</span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" data-act="mobile-menu" aria-label="Abrir menú">${icon('menu')}</button><span>Espacio de trabajo</span>${icon('chevron')}<strong>${views[state.view]}</strong></div><div class="top-actions"><span class="sync-text"><i class="live-dot"></i>${esc(s.database?.engine||'Base de datos')} conectado</span><button data-act="refresh" title="Actualizar datos" aria-label="Actualizar datos">${icon('refresh')}</button><div class="top-separator"></div><button data-view="plan" title="Revisar alertas de inventario" aria-label="Revisar alertas">${icon('bell')}<i class="notification-dot"></i></button><span class="avatar">${initials(u.name)}</span></div></header><div class="content" id="content"></div></main></div>`;
 $('#workspace-search').addEventListener('input',e=>{state.search=e.target.value;$('#tree').innerHTML=treeHtml()});
 renderContent();
}
const pageHeader=(title,subtitle,buttons='',eyebrow='Tu espacio, conectado')=>`<div class="page-header"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="header-buttons">${buttons}</div></div>`;
const footer=()=>`<footer class="workspace-bottom"><span>${icon('shield')}Tus datos se guardan en este servidor · Acceso por sede</span><div class="footer-links"><span>American Texas Chicken</span><span>Hecho para anticipar</span></div><button class="floating-help" data-act="help" aria-label="Ayuda">?</button></footer>`;
function fileTable(){let files=state.summary.files.filter(f=>(!state.branch||f.sedes.includes(state.branch))&&f.name.toLowerCase().includes(state.fileSearch.toLowerCase()));if(state.sort==='name')files.sort((a,b)=>a.name.localeCompare(b.name));return `<div class="table-wrap"><table><thead><tr><th>Nombre ${icon('down')}</th><th>Subido por</th><th>Fecha de carga</th><th>Estado</th><th></th></tr></thead><tbody>${files.map((f,i)=>`<tr><td><a class="file-name" href="/api/files/${encodeURIComponent(f.id)}/download" title="Descargar datos normalizados"><span class="file-icon ${i===1?'gray':''}">${icon('files')}</span><span>${esc(f.name)}<small>${fmt(f.row_count)} registros · ${f.sedes.length} ${f.sedes.length===1?'sede':'sedes'}</small></span></a></td><td><div class="user-cell"><span class="avatar ${i===1?'peach':i===2?'gray':''}">${initials(f.uploader)}</span><span class="email">${esc(f.email)}</span></div></td><td>${shortDate(f.created)}<span class="muted small">, ${f.created.slice(0,4)}</span></td><td>${badge('Procesado','green')}</td><td><a href="/api/files/${encodeURIComponent(f.id)}/download" class="icon-btn" title="Descargar Excel normalizado" aria-label="Descargar ${esc(f.name)}">${icon('download')}</a></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No hay archivos para esta selección.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${files.length} archivos en tu espacio</span><span>${icon('check')} Todo al día</span></div>`}
function homeView(filesOnly=false){const s=state.summary;const cards=state.tree==='productos'?s.products.map((name,i)=>({name,files:s.files.length,products:0,i,product:true})):s.sedes.map((r,i)=>({...r,i}));return `${pageHeader(filesOnly?'Tus datos, en un solo lugar.':'Tu operación, en orden.',filesOnly?'Sube tus ventas, revisa su calidad y déjanos hacer los cálculos.':'Una visión clara de tus sedes. Mejores decisiones para cada servicio.',`<a class="button" href="/api/template">${icon('download')} Plantilla</a><button class="button primary" data-act="upload">${icon('plus')} Subir archivo</button>`,filesOnly?'Datos y archivos':`Hola, ${esc(state.user.name.split(' ')[0])} · American Texas Chicken`)}${!filesOnly?`<div class="metrics">${metric('Sedes conectadas',`${s.sedes.length}<span class="unit">sedes</span>`,'Una operación, un mismo lugar','building')}${metric('Ventas registradas',fmt(s.rows),'Registros disponibles para entrenar','files')}${metric('Calidad de datos',s.rows?`${fmt(s.quality,1)}<span class="unit">%</span>`:'—','Calidad al momento de la carga','shield')}${metric('Historial disponible',`${s.date_start?Math.round((new Date(s.date_end)-new Date(s.date_start))/86400000)+1:0}<span class="unit">días</span>`,s.date_start?shortDate(s.date_start)+' — '+shortDate(s.date_end):'Sube tu primer archivo','calendar')}</div>`:''}<section><div class="section-heading"><div class="title-with-count"><h2>${state.tree==='productos'?'Productos':'Carpetas de sedes'}</h2><span class="count">${cards.length}</span></div><div class="section-right"><select class="select" data-change="folder-category" aria-label="Organizar carpetas" style="border:0;padding:0;min-height:22px;background:none;font-size:10px"><option value="sedes" ${state.tree==='sedes'?'selected':''}>Por sede</option><option value="productos" ${state.tree==='productos'?'selected':''}>Por producto</option></select><div class="view-toggle"><button data-act="folder-view" data-mode="grid" class="${state.folderView==='grid'?'active':''}" aria-label="Vista de tarjetas">${icon('grid')}</button><button data-act="folder-view" data-mode="list" class="${state.folderView==='list'?'active':''}" aria-label="Vista de lista">${icon('list')}</button></div></div></div><div class="folder-grid ${state.folderView==='list'?'list':''} ${state.tree==='productos'?'product-grid':''}">${cards.map(s=>`<button class="folder-card" data-act="${s.product?'select-product':'open-branch'}" ${s.product?`data-product="${esc(s.name)}"`:`data-branch="${esc(s.name)}"`}><div class="folder-top"><div class="source-icons"><span class="source-circle" title="Excel">X</span><span class="source-circle csv" title="CSV">${icon('files')}</span><span class="source-circle pos" title="Datos de ventas">${icon('chart')}</span></div><span class="folder-menu">${icon('more')}</span></div>${folderArt(s.i)}<h3>${esc(s.name)}</h3><div class="folder-meta"><span>${s.files} ${s.files===1?'archivo':'archivos'}${s.products?' · '+s.products+' productos':''}</span>${icon('arrow')}</div></button>`).join('')}</div></section><div class="upload-strip" id="quick-drop"><div class="upload-icon">${icon('upload')}</div><div><strong>Tu próxima predicción empieza con tus datos</strong><p>Arrastra aquí tus ventas históricas · Excel o CSV · hasta 15 MB</p></div><button class="button small-btn" data-act="upload">Explorar archivos ${icon('arrow')}</button></div><section><div class="section-heading"><div class="title-with-count"><h2>Archivos recientes</h2><span class="count">${s.files.length}</span></div><div class="section-right"><label class="table-search">${icon('search')}<input id="file-search" aria-label="Buscar archivos" placeholder="Buscar archivo" value="${esc(state.fileSearch)}"></label><select class="select" data-change="sort-files" aria-label="Ordenar archivos" style="border:0;min-height:20px;padding:0;font-size:10px"><option value="recent" ${state.sort==='recent'?'selected':''}>Más recientes</option><option value="name" ${state.sort==='name'?'selected':''}>Nombre A–Z</option></select></div></div>${state.branch?`<div class="branch-detail"><p>${icon('pin')} Mostrando ${esc(state.branch)} <button data-act="clear-branch" class="small">Quitar filtro ×</button></p></div>`:''}<div id="file-table">${fileTable()}</div></section>${footer()}`}
function filters(includeHorizon=true,includeProduct=true){return `<div class="filters">${includeHorizon?`<div class="segmented">${[[1,'Mañana'],[7,'Próximos 7 días'],[30,'Próximos 30 días']].map(([n,t])=>`<button data-act="horizon" data-horizon="${n}" class="${state.horizon===n?'active':''}">${t}</button>`).join('')}</div>`:''}<select class="select" data-change="branch" aria-label="Filtrar sede">${branchOptions()}</select>${includeProduct?`<select class="select" data-change="product" aria-label="Filtrar producto">${productOptions()}</select>`:''}</div>`}
async function ensureForecast(){if(!state.forecast)state.forecast=await api('/forecast?'+query());return state.forecast}
async function ensureHistory(){if(!state.history)state.history=await api('/history');return state.history}
async function ensurePlan(){const params=query();params.set('margin',state.margin);if(!state.plan)state.plan=await api('/plan?'+params);return state.plan}
async function predictionView(compare=false){const [forecast,history]=await Promise.all([ensureForecast(),ensureHistory()]);const rows=filtered(forecast.rows),hist=filtered(history.daily),metrics=filtered(forecast.metrics);const total=rows.reduce((a,r)=>a+r.esperado,0);const mape=metrics.filter(m=>m.mape!==null);const avg=mape.length?mape.reduce((a,r)=>a+r.mape,0)/mape.length:null;return `${pageHeader(compare?'Cada sede, una perspectiva.':'Anticípate al próximo servicio.',compare?'Encuentra patrones y compara la demanda de tus locales.':'De tus ventas históricas a un plan que puedes poner en marcha.',`<button class="button" data-view="events">${icon('cloud')} Eventos y clima</button><button class="button primary" data-view="plan">Ver plan de preparación ${icon('arrow')}</button>`,'Inteligencia para tu cocina')}${filters()}<div class="metrics">${metric('Demanda esperada',fmt(total)+'<span class="unit">porciones</span>',`Horizonte de ${state.horizon} ${state.horizon===1?'día':'días'}`,'trend')}${metric('Escenario mínimo',fmt(rows.reduce((a,r)=>a+r.minimo,0)),'Suma de límites orientativos','chart')}${metric('Escenario máximo',fmt(rows.reduce((a,r)=>a+r.maximo,0)),'Útil para planificar capacidad','chart')}${metric('Error en backtesting',avg===null?'—':fmt(avg,1)+'<span class="unit">% MAPE</span>',avg===null?'Aún no hay datos suficientes':'Menor es mejor · promedio de series','shield')}</div><section class="panel"><div class="panel-header"><div><h2>De lo que vendiste a lo que viene</h2><p class="muted small" style="margin:6px 0 0">Porciones por día · últimos 28 días y pronóstico</p></div><div class="legend"><span><i></i>Histórico</span><span><i class="forecast"></i>Predicción</span><span><i class="range"></i>Rango</span></div></div>${chart(hist,rows)}</section><div class="chart-grid"><section class="panel"><div class="panel-header"><h2>Demanda por sede</h2><span class="muted small">${state.horizon} días · porciones</span></div>${bars(rows)}</section><section class="panel"><div class="panel-header"><h2>Tu ritmo de ventas</h2><span class="muted small">Promedio por día y hora</span></div>${heatmap(filtered(history.heatmap))}<p class="muted small" style="margin:12px 0 0">Menor ░░░ ▓▓▓ Mayor · celdas claras: sin registro horario</p></section></div>${note(forecast.interval_note)}${note(forecast.weather_note)}${forecast.warnings.length?note(forecast.warnings.slice(0,3).join(' ')+(forecast.warnings.length>3?` Hay ${forecast.warnings.length} avisos; consulta la evaluación.`:''),'amber'):''}<section class="panel"><div class="panel-header"><h2>Próximos servicios</h2><span class="muted small">${forecast.method}</span></div><div class="table-wrap"><table><thead><tr><th>Día / sede</th><th>Producto</th><th>Turno</th><th>Mínimo</th><th>Esperado</th><th>Máximo</th><th>Confianza</th></tr></thead><tbody>${rows.slice(0,48).map(r=>`<tr><td>${shortDate(r.fecha)}<small style="display:block;margin-top:4px">${esc(r.sede)}</small></td><td>${esc(r.producto)}</td><td>${esc(r.turno)}</td><td>${fmt(r.minimo)}</td><td><strong>${fmt(r.esperado)}</strong></td><td>${fmt(r.maximo)}</td><td>${badge(r.confidence,r.confidence==='Alta'?'green':r.confidence==='Media'?'neutral':'amber')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No hay predicciones para esta selección.</td></tr>'}</tbody></table></div><div class="table-footer"><span>Mostrando ${Math.min(rows.length,48)} de ${rows.length} predicciones. El Excel incluye todas.</span><button data-act="export-xlsx" class="small">Descargar todas ${icon('download')}</button></div></section>${footer()}`}
function exportUrl(kind){const params=query();params.set('margin',state.margin);if(state.branch)params.set('sede',state.branch);if(state.day)params.set('day',state.day);return '/api/export/'+kind+'?'+params}
async function planView(){const plan=await ensurePlan();const rows=plan.rows.filter(r=>(!state.branch||r.sede===state.branch)&&(!state.day||r.fecha===state.day));const prep=filtered(plan.preparation).filter(r=>!state.day||r.fecha===state.day);const grouped={};prep.forEach(r=>grouped[r.producto]=(grouped[r.producto]||0)+r.porciones);const days=[...new Set(plan.rows.map(r=>r.fecha))];return `${pageHeader('Una lista. Todo listo.','Qué comprar y cuánto preparar, para cada sede y cada día.',`<button class="button" data-act="export-pdf">${icon('download')} PDF</button><button class="button primary" data-act="export-xlsx">${icon('download')} Exportar Excel</button>`,'Tu plan de preparación')}${filters()}<div class="filters"><select class="select" data-change="day" aria-label="Filtrar día"><option value="">Todos los días del horizonte</option>${days.map(d=>`<option value="${d}" ${state.day===d?'selected':''}>${shortDate(d)}</option>`).join('')}</select><span class="horizon-label">El stock se descuenta día a día, sin reutilizarlo.</span></div><div class="metrics">${metric('Compra estimada',rows.some(r=>r.costo===null)?'Pendiente':money(rows.reduce((a,r)=>a+r.costo,0)),'Costo de cubrir la demanda esperada','box','money')}${metric('Déficits detectados',fmt(rows.filter(r=>r.estado==='quiebre').length),'Insumos / sede / día que requieren compra','bell')}${metric('Riesgos de excedente',fmt(rows.filter(r=>r.estado==='excedente').length),'Revisar rotación y caducidad','clock')}${metric('Ahorro potencial',savingsAmount(plan),savingsScope(plan)+' del periodo','trend','money')}</div><div class="section-heading"><span class="muted small">Referencia de ahorro: patrón semanal + ${fmt(state.margin*100)} % de margen</span><button class="button small-btn" data-view="savings">Ver cálculo del ahorro ${icon('arrow')}</button></div><div class="prep-grid" style="margin-bottom:25px">${Object.entries(grouped).map(([name,n])=>`<div class="prep-card">${icon('utensils')}<h3>${esc(name)}</h3><strong>${fmt(n)}</strong> <span class="muted small">porciones</span><p>Preparación estimada del período seleccionado</p></div>`).join('')}</div>${plan.missing_recipes.length?note('Faltan recetas para: '+plan.missing_recipes.join(', ')+'. Configúralas para incluir sus insumos.','error'):''}<section class="panel"><div class="panel-header"><h2>Compras y preparación de insumos</h2><span class="muted small">kg, L o unidades · según receta</span></div><div class="table-wrap"><table><thead><tr><th>Día / sede</th><th>Insumo</th><th>Preparar</th><th>Stock disponible</th><th>Comprar</th><th>Acción</th><th>Estado</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${shortDate(r.fecha)}<small style="display:block;margin-top:4px">${esc(r.sede)}</small></td><td>${esc(r.insumo)}</td><td><strong>${fmt(r.requerido,2)} ${r.unidad}</strong></td><td>${r.inventario===null?'Sin registrar':fmt(r.inventario,2)+' '+r.unidad}</td><td>${r.comprar===null?'Pendiente':r.comprar>0?`<span class="danger">${fmt(r.comprar,2)} ${r.unidad}</span>`:'—'}</td><td>${esc(r.accion)}</td><td>${badge(r.estado==='pendiente'?'Registrar stock':r.estado==='quiebre'?'Comprar':r.estado==='excedente'?'Revisar excedente':'Óptimo',r.estado==='pendiente'?'neutral':r.estado==='quiebre'?'red':r.estado==='excedente'?'amber':'green')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No hay recomendaciones para esta selección.</td></tr>'}</tbody></table></div></section>${note(plan.note)}${note('Desperdicio estimado y quiebres evitados: pendientes de medición. Los riesgos detectados no equivalen a pérdidas reales ni a quiebres ya evitados.')}${note('Marinar y prefritar son tareas de planificación. Los tiempos, temperaturas y límites de conservación deben seguir el procedimiento operativo de la cocina.')}${footer()}`}
async function inventoryView(){const rows=await api('/inventory');const filteredRows=rows.filter(r=>!state.branch||r.sede===state.branch);return `${pageHeader('Lo que tienes, a la vista.','Actualiza las existencias antes de generar tu plan de compras.',`<a class="button" href="/api/template?kind=inventario">${icon('download')} Plantilla</a><button class="button primary" data-act="upload-inventory">${icon('upload')} Subir inventario</button>`,'Inventario por sede')}<div class="filters"><select class="select" data-change="branch" aria-label="Filtrar sede">${branchOptions()}</select><button class="button" data-act="new-inventory">${icon('plus')} Agregar existencia</button><button class="button subtle" data-view="plan">Comparar con demanda ${icon('arrow')}</button></div><section class="panel"><div class="panel-header"><h2>Existencias actuales</h2><span class="muted small">Actualiza una cantidad y pulsa guardar</span></div><div class="table-wrap"><table><thead><tr><th>Sede</th><th>Insumo</th><th>Unidad</th><th>Costo de referencia</th><th>Disponible</th><th></th></tr></thead><tbody>${filteredRows.map((r,i)=>`<tr><td>${esc(r.sede)}</td><td>${esc(r.insumo)}</td><td>${r.unit}</td><td>${r.cost===null?'Sin configurar':money(r.cost)+' / '+r.unit}</td><td><input type="number" class="editable" id="stock-${i}" min="0" max="10000000" step="0.01" value="${r.amount}" aria-label="Cantidad de ${esc(r.insumo)} en ${esc(r.sede)}"></td><td><button class="button small-btn" data-act="save-stock" data-id="${i}" data-branch="${esc(r.sede)}" data-ingredient="${esc(r.insumo)}">${icon('save')} Guardar</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Esta sede no tiene inventario. Agrega existencias o sube un archivo.</td></tr>'}</tbody></table></div></section>${note('Ingresa tus existencias reales y configura el costo por insumo en Recetas. El inventario importado debe usar las mismas unidades: kg, L y und. El plan proyecta consumo, pero no descuenta stock real hasta que actualices las existencias.')}${footer()}`}
async function recipesView(){
 const rows=(await api('/recipes')).map((row,index)=>({...row,index}));
 const products=[...new Set([...state.summary.products,...rows.map(r=>r.producto)])];
 const descriptions={'Pollo broaster':'1 porción de pollo','Hamburguesa':'1 hamburguesa','Alitas BBQ':'1 porción de alitas','Salchipapa':'1 porción de salchipapa'};
 const admin=state.user.role==='admin';
 const sections=products.filter(p=>!state.product||p===state.product).map(product=>{
  const ingredients=rows.filter(r=>r.producto===product);
  const potato=ingredients.find(r=>r.insumo==='Papa');
  const description=(descriptions[product]||'Cantidades por una porción')+(potato&&product!=='Salchipapa'?' con '+fmt(potato.amount*1000)+' g de papas':'');
  return `<section class="panel recipe-panel"><div class="panel-header"><div><h2>${esc(product)}</h2><p class="muted small" style="margin:7px 0 0">${esc(description)}</p></div><span class="count">${ingredients.length} ingredientes</span></div><div class="table-wrap"><table><thead><tr><th>Ingrediente</th><th>Por porción</th><th>Medida</th>${admin?'<th></th>':''}</tr></thead><tbody>${ingredients.map(r=>{
   const factor=r.unit==='kg'||r.unit==='L'?1000:1,unit=r.unit==='kg'?'g':r.unit==='L'?'mL':r.unit;
   const amount=Math.round(r.amount*factor*1000)/1000;
   return `<tr><td>${esc(r.insumo)}</td><td><div class="recipe-quantity">${admin?`<input class="editable" id="recipe-${r.index}" type="number" value="${amount}" min="0.001" step="0.001" aria-label="${esc(r.insumo)} por porción de ${esc(product)} en ${unit}">`:fmt(amount,amount%1?2:0)}<span>${unit}</span></div></td><td>${badge(r.approximate?'Aprox.':'Ajustada',r.approximate?'amber':'green')}</td>${admin?`<td><div class="action-row"><button class="icon-btn" data-act="save-recipe" data-id="${r.index}" data-factor="${factor}" data-product="${esc(product)}" data-ingredient="${esc(r.insumo)}" title="Guardar medida" aria-label="Guardar ${esc(r.insumo)} de ${esc(product)}">${icon('save')}</button><button class="icon-btn" data-act="remove-recipe" data-product="${esc(product)}" data-ingredient="${esc(r.insumo)}" title="Quitar ingrediente" aria-label="Quitar ${esc(r.insumo)} de ${esc(product)}">${icon('trash')}</button></div></td>`:''}</tr>`;
  }).join('')||`<tr><td colspan="4" class="empty">Agrega los ingredientes de este producto.</td></tr>`}</tbody></table></div></section>`;
 }).join('');
 return `${pageHeader('Una receta para planificar mejor.','Ingredientes y medidas de referencia por porción. Ajusta cada receta a tu cocina.',admin?'<button class="button primary" data-act="new-recipe">'+icon('plus')+' Agregar ingrediente</button>':'','Recetas estándar')}${note('Las medidas marcadas como Aprox. son orientativas. Guardar una cantidad la marca como ajustada por tu cocina. Las guarniciones de papas están incluidas: puedes modificar o quitar ingredientes. El aceite representa consumo estimado por porción, no el llenado de la freidora.','amber')}${!admin?note('Tu rol permite consultar recetas. El administrador puede modificarlas.'):''}<div class="filters"><select class="select" data-change="product" aria-label="Filtrar producto"><option value="">Todos los productos</option>${products.map(p=>`<option ${state.product===p?'selected':''}>${esc(p)}</option>`).join('')}</select><span class="muted small">Medidas en g, mL y unidades · 1 huevo = 4 porciones si se usa 0,25 und</span></div><div class="recipe-grid ${state.product?'single':''}">${sections}</div>${admin?`<details class="recipe-costs"><summary>${icon('box')} Configurar costos de compra <span class="muted small">S/ por kg, L o unidad</span></summary>${costEditor()}</details>`:''}${note('El sistema convierte automáticamente gramos a kg y mL a L para descontar inventario. Los costos sin configurar quedan pendientes. Las medidas de esta guía no representan la formulación oficial del negocio.')}${footer()}`;
}
async function evaluationView(){const f=await ensureForecast();return renderEvaluation(f,filtered(f.metrics),filtered(f.backtests),{pageHeader,filters,footer,note})}
function eventsView(){return `${pageHeader('Hay días que cambian el ritmo.','Añade festividades o eventos y explora su impacto en la demanda.',`<button class="button primary" data-act="new-event">${icon('plus')} Agregar evento</button>`,'Eventos y clima')}<div class="event-weather"><section class="panel"><div class="panel-header"><h2>Tu calendario local</h2>${icon('calendar')}</div>${state.summary.events.map(e=>`<div class="event-row"><span class="event-date">${shortDate(e.fecha)}</span><div>${esc(e.name)}<small>${esc(e.sede||'Todas las sedes')} · escenario +${fmt(e.impact*100)} %</small></div><button class="icon-btn" data-act="delete-event" data-id="${e.id}" aria-label="Eliminar ${esc(e.name)}">${icon('trash')}</button></div>`).join('')||'<div class="empty">Tu calendario está listo para el próximo evento.</div>'}${note('Registra la Semana Turística, el aniversario que corresponda en junio y conciertos como el de la Plaza Huamanmarca. Confirma las fechas con la organización; no se han fijado fechas locales sin verificar.')}</section><section class="panel"><div class="panel-header"><h2>Clima del próximo servicio</h2>${icon('cloud')}</div><p class="muted small">Escenario constante para el horizonte seleccionado. Déjalo vacío para utilizar el clima histórico.</p><div class="weather-fields"><div><label class="field-label" for="weather-temp">Temperatura (°C)</label><input class="field" id="weather-temp" type="number" min="-30" max="55" step="0.1" placeholder="Mediana histórica" value="${state.temperature}"></div><div><label class="field-label" for="weather-rain">Lluvia (mm)</label><input class="field" id="weather-rain" type="number" min="0" max="500" step="0.1" placeholder="Mediana histórica" value="${state.rain}"></div></div><button class="button primary" data-act="save-weather">Aplicar escenario ${icon('arrow')}</button>${note('Puedes incluir temperatura y lluvia en tus archivos de ventas. No se consulta una API meteorológica en vivo.')}</section></div><section class="panel"><div class="panel-header"><h2>Feriados de Perú, por año</h2>${badge('Calendario integrado')}</div><p class="muted small">El modelo usa el calendario nacional de la biblioteca holidays para la fecha correspondiente, incluyendo feriados móviles. Los cambios normativos deben contrastarse con el calendario oficial vigente y la versión de la biblioteca.</p></section>${note('El incremento de un evento es una hipótesis que tú defines, no un efecto causal aprendido. Se aplica a la demanda de ese día. Si coinciden eventos, se usa el mayor incremento para evitar duplicarlo.')}${footer()}`}
async function renderContent(){const id=++state.renderId,view=state.view;const content=$('#content');if(!content)return;content.innerHTML=loading(['forecast','evaluation','compare','plan','savings','ml'].includes(view)?'Calculando con tus datos. El primer entrenamiento puede tardar unos segundos…':'Cargando…');try{let html;if(['forecast','compare','plan','evaluation','savings','ml'].includes(view)&&state.summary.rows===0){content.innerHTML=pageHeader('Empieza con tus ventas reales.','Tu base está conectada. Carga el historial para calcular demanda e insumos.',`<button class="button primary" data-act="upload">${icon('upload')} Cargar ventas</button>`,'Operación conectada')+note('Todavía no hay ventas registradas. El sistema no genera pronósticos sin datos reales.')+footer();return}if(view==='home'||view==='files')html=homeView(view==='files');else if(view==='forecast'||view==='compare')html=await predictionView(view==='compare');else if(view==='plan')html=await planView();else if(view==='inventory')html=await inventoryView();else if(view==='recipes')html=await recipesView();else if(view==='evaluation')html=await evaluationView();else if(view==='savings')html=await savingsView();else if(view==='ml')html=await mlView();else if(view==='database')html=await databaseView();else html=eventsView();if(id!==state.renderId)return;content.innerHTML=html;const drop=$('#quick-drop');if(drop)bindDrop(drop,file=>openUpload(file));const search=$('#file-search');if(search)search.oninput=e=>{state.fileSearch=e.target.value;$('#file-table').innerHTML=fileTable()}}catch(e){if(id===state.renderId)content.innerHTML=pageHeader('Revisemos los datos.','Necesitamos resolver este detalle para continuar.')+note(e.message,'error')+'<button class="button" data-act="upload">Subir archivo</button> <button class="button" data-act="retry-view">Volver a intentar</button>'}}
function navigate(view){if(!views[view])return;if(view!=='ml')stopModelPlayback();state.view=view;location.hash=view;renderShell();window.scrollTo(0,0)}
function bindDrop(element,onFile){['dragenter','dragover'].forEach(type=>element.addEventListener(type,e=>{e.preventDefault();element.classList.add('drag')}));['dragleave','drop'].forEach(type=>element.addEventListener(type,e=>{e.preventDefault();element.classList.remove('drag')}));element.addEventListener('drop',e=>{if(e.dataTransfer.files[0])onFile(e.dataTransfer.files[0])})}
let upload={};
const issueNames={vacios:'Valores vacíos',fechas_invalidas:'Fechas inválidas',cantidades_invalidas:'Cantidades inválidas',negativos:'Cantidades negativas',duplicados:'Filas duplicadas',outliers:'Valores atípicos',variables_invalidas:'Clima, hora o turno inválidos'};
const issueOptions={vacios:[['eliminar','Eliminar filas'],['rellenar','Rellenar cantidad']],fechas_invalidas:[['eliminar','Eliminar filas']],cantidades_invalidas:[['eliminar','Eliminar filas'],['rellenar','Usar mediana']],negativos:[['eliminar','Eliminar filas'],['rellenar','Usar mediana']],duplicados:[['eliminar','Conservar primera'],['ignorar','Sumar cantidades']],outliers:[['ignorar','Conservar'],['eliminar','Eliminar filas'],['rellenar','Usar mediana']],variables_invalidas:[['eliminar','Eliminar filas'],['rellenar','Vaciar / corregir']]};
function openUpload(file){upload={file:null,preview:null,report:null,mapping:{},policies:{}};renderUpload(1);if(file)inspectFile(file)}
function renderUpload(step){
 const p=upload.preview,r=upload.report;
 const stepper=`<div class="stepper">${['Seleccionar archivo','Mapear columnas','Revisar y cargar'].map((s,i)=>`<span class="${i+1===step?'active':''}"><b>${i+1}</b>${s}</span>`).join('')}</div>`;
 let body='',foot='';
 if(step===1){body=`<div class="drop-zone" id="upload-drop" tabindex="0" role="button" aria-label="Seleccionar archivo">${icon('upload')}<p>Arrastra tus ventas históricas aquí</p><small>o haz clic para explorar · .xlsx, .xls, .csv · máximo 15 MB</small></div><input type="file" id="file-input" accept=".xlsx,.xls,.csv" hidden><div id="upload-progress"></div>${note('Primero verás una vista previa. Nada se importa hasta que revises y confirmes los datos.')}`;foot='<a class="button subtle" href="/api/template">'+icon('download')+' Descargar plantilla</a><button class="button" data-act="close-modal">Cancelar</button>'}
 if(step===2){body=`<div class="note-box">${icon('files')}<span>${esc(upload.file.name)} · ${fmt(p.total)} filas${p.encoding?' · '+esc(p.encoding)+' · separador '+(p.separator==='\t'?'tabulación':esc(p.separator)):''}</span></div>${p.sheets.length>1?`<label class="field-label" for="sheet-select">Hoja de Excel</label><select class="field select" id="sheet-select" data-change="sheet" style="margin-bottom:18px">${p.sheets.map(s=>`<option ${s===p.sheet?'selected':''}>${esc(s)}</option>`).join('')}</select>`:''}<h3>Relaciona las columnas de tu archivo</h3><div class="mapping-grid">${['fecha','sede','producto','cantidad','turno','hora','temperatura','lluvia','evento'].map(k=>`<div><label class="field-label" for="map-${k}">${({cantidad:'Cantidad vendida',temperatura:'Temperatura (°C)',lluvia:'Lluvia (mm)',evento:'Incremento de evento (0–3)',hora:'Hora (0–23)'})[k]||k.charAt(0).toUpperCase()+k.slice(1)} ${['fecha','sede','producto','cantidad'].includes(k)?'*':'· opcional'}</label><select class="field" id="map-${k}" data-map="${k}"><option value="">Seleccionar columna</option>${p.columns.map(c=>`<option value="${esc(c)}" ${upload.mapping[k]===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div>`).join('')}</div><h3 style="margin:23px 0 10px">Vista previa · primeras ${Math.min(p.total,20)} filas</h3><div class="preview-table"><table><thead><tr>${p.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${p.preview.map(row=>`<tr>${p.columns.map(c=>`<td>${esc(row[c]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${note('Usa una fila por fecha, sede, producto y turno. Los totales importados reemplazan los existentes con la misma clave; no se duplican. Hora, clima y evento deben ser numéricos.')}`;foot='<button class="button" data-act="upload-back" data-step="1">Cambiar archivo</button><button class="button primary" data-act="validate-file">Validar datos '+icon('arrow')+'</button>'}
 if(step===3){body=`<div class="quality-score"><div class="quality-number">${fmt(r.quality,1)}%</div><div><strong>de filas sin observaciones</strong><p>${fmt(r.valid_rows)} de ${fmt(r.rows)} registros · ${r.sedes} sedes · ${r.products} productos</p><p>${r.date_start?shortDate(r.date_start)+' — '+shortDate(r.date_end):'Sin fechas válidas'}</p></div></div><h3>Elige cómo resolver las observaciones</h3>${Object.entries(r.issues).map(([k,n])=>`<div class="issue-row"><div>${issueNames[k]}${n?`<small class="muted" style="display:block;font-size:8px;margin-top:3px">Filas ${r.samples[k].join(', ')}${n>12?'…':''}</small>`:''}</div><span class="count">${n}</span><select class="select" data-policy="${k}" ${n?'':'disabled'}>${issueOptions[k].map(([v,l])=>`<option value="${v}" ${(upload.policies[k]||issueOptions[k][0][0])===v?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}${note('Rellenar usa la mediana de cantidad por sede, producto y turno. Nunca se inventan fechas, sedes o productos: si faltan, se elimina la fila. Los outliers conservados siguen siendo visibles en este informe.')}<div id="import-error"></div>`;foot='<button class="button" data-act="upload-back" data-step="2">Revisar columnas</button><button class="button primary" data-act="import-file">'+icon('check')+' Importar y actualizar modelo</button>'}
 modal('Cargar ventas históricas',stepper+body,foot);
 if(step===1){$('#file-input').onchange=e=>{if(e.target.files[0])inspectFile(e.target.files[0])};$('#upload-drop').onclick=()=>$('#file-input').click();$('#upload-drop').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#file-input').click()}};bindDrop($('#upload-drop'),inspectFile)}
}
async function inspectFile(file,sheet){if(!/\.(xlsx|xls|csv)$/i.test(file.name)){toast('Selecciona un archivo Excel o CSV.',true);return}if(file.size>15*1024*1024){toast('El límite por archivo es 15 MB.',true);return}upload.file=file;const data=new FormData();data.append('file',file);if(sheet)data.append('sheet',sheet);const progress=$('#upload-progress');if(progress)progress.innerHTML=loading('Leyendo archivo…');try{upload.preview=await api('/uploads/preview',{method:'POST',body:data});upload.mapping={...upload.preview.mapping};renderUpload(2)}catch(e){toast(e.message,true);if(progress)progress.innerHTML=note(e.message,'error')}}
function eventModal(){modal('Agregar evento especial',`<form id="event-form" class="form-stack"><div><label class="field-label" for="event-name">Nombre del evento</label><input class="field" id="event-name" required minlength="2" maxlength="120" placeholder="Concierto en la Plaza Huamanmarca"></div><div><label class="field-label" for="event-date">Fecha confirmada</label><input class="field" type="date" id="event-date" required></div><div><label class="field-label" for="event-sede">Sede</label><select class="field" id="event-sede">${branchOptions(state.user.role==='admin')}</select></div><div><label class="field-label" for="event-impact">Incremento esperado (%)</label><input class="field" type="number" id="event-impact" min="0" max="300" step="1" value="15" required></div>${note('Un +15 % es un escenario que tú propones. Se aplica solo a la fecha y sede seleccionadas.')}<button class="button primary">Guardar evento</button></form>`,'',true);$('#event-form').onsubmit=async e=>{e.preventDefault();try{await api('/events',{method:'POST',body:json({name:$('#event-name').value,fecha:$('#event-date').value,sede:$('#event-sede').value||null,impact:Number($('#event-impact').value)/100})});$('#modal-root').innerHTML='';await refresh();renderShell();toast('Evento agregado. El modelo se actualizará.')}catch(e){toast(e.message,true)}}}
function newRecipe(){modal('Agregar ingrediente a una receta',`<form id="recipe-form" class="form-stack"><div><label class="field-label" for="new-product">Producto</label><input id="new-product" class="field" list="product-list" required maxlength="100"><datalist id="product-list">${state.summary.products.map(p=>`<option value="${esc(p)}">`).join('')}</datalist></div><div><label class="field-label" for="new-ingredient">Insumo · unidad de compra</label><select class="field" id="new-ingredient">${state.summary.ingredients.map(i=>`<option value="${esc(i.name)}">${esc(i.name)} (${i.unit})</option>`).join('')}</select></div><div><label class="field-label" for="new-amount">Cantidad por porción, en la unidad seleccionada</label><input type="number" step="0.001" min="0.001" max="10000" id="new-amount" class="field" required></div><button class="button primary">Guardar ingrediente</button></form>`,'',true);$('#recipe-form').onsubmit=async e=>{e.preventDefault();try{await api('/recipes',{method:'PUT',body:json({producto:$('#new-product').value,insumo:$('#new-ingredient').value,amount:Number($('#new-amount').value)})});state.summary=await api('/summary');state.plan=null;$('#modal-root').innerHTML='';renderContent();toast('Receta actualizada.')}catch(e){toast(e.message,true)}}}
function newInventory(){modal('Agregar existencia',`<form id="stock-form" class="form-stack"><div><label class="field-label" for="new-stock-sede">Sede</label><select class="field" id="new-stock-sede">${branchOptions(false)}</select></div><div><label class="field-label" for="new-stock-ingredient">Insumo · unidad</label><select class="field" id="new-stock-ingredient">${state.summary.ingredients.map(i=>`<option value="${esc(i.name)}">${esc(i.name)} (${i.unit})</option>`).join('')}</select></div><div><label class="field-label" for="new-stock-amount">Cantidad disponible</label><input type="number" id="new-stock-amount" class="field" required min="0" max="10000000" step="0.01"></div><button class="button primary">Guardar existencia</button></form>`,'',true);$('#stock-form').onsubmit=async e=>{e.preventDefault();try{await api('/inventory',{method:'PUT',body:json({sede:$('#new-stock-sede').value,insumo:$('#new-stock-ingredient').value,amount:Number($('#new-stock-amount').value)})});state.plan=null;$('#modal-root').innerHTML='';renderContent();toast('Inventario actualizado.')}catch(e){toast(e.message,true)}}}
function uploadInventory(){modal('Cargar inventario',`<p class="muted small">Columnas requeridas: sede, insumo, cantidad, unidad. Las cantidades reemplazan las existencias actuales de cada insumo.</p><input type="file" class="field" id="inventory-file" accept=".csv,.xlsx,.xls"><div id="inventory-upload-note"></div><p><a href="/api/template?kind=inventario" class="button subtle">${icon('download')} Descargar plantilla</a></p>`,'<button class="button" data-act="close-modal">Cancelar</button><button class="button primary" data-act="import-inventory">Actualizar inventario</button>',true)}
const actions={
 'close-modal':()=>$('#modal-root').innerHTML='',
 'upload':()=>openUpload(),
 'retry-view':()=>renderContent(),
 'refresh':async()=>{await refresh();renderShell();toast('Datos actualizados.')},
 'mobile-menu':()=>$('#sidebar').classList.toggle('open'),
 'close-sidebar':()=>$('#sidebar').classList.remove('open'),
 'tree-toggle':el=>{const s=el.dataset.branch;state.expanded.has(s)?state.expanded.delete(s):state.expanded.add(s);$('#tree').innerHTML=treeHtml()},
 'tree-tab':el=>{state.tree=el.dataset.tab;renderShell()},
 'folder-view':el=>{state.folderView=el.dataset.mode;renderContent()},
 'open-branch':el=>{state.branch=el.dataset.branch;state.product='';navigate('forecast')},
 'branch-files':el=>{state.branch=el.dataset.branch;navigate('files')},
 'select-series':el=>{state.branch=el.dataset.branch;state.product=el.dataset.product;navigate('forecast')},
 'select-product':el=>{state.product=el.dataset.product;state.branch='';navigate('forecast')},
 'clear-branch':()=>{state.branch='';renderContent()},
 'horizon':el=>{state.horizon=Number(el.dataset.horizon);state.forecast=null;state.plan=null;state.mlCache=null;state.mlDay=0;state.day='';renderContent()},
 'export-xlsx':()=>{location.href=exportUrl('xlsx')},
 'export-pdf':()=>{location.href=exportUrl('pdf')},
 'new-event':()=>eventModal(),
 'delete-event':async el=>{await api('/events/'+el.dataset.id,{method:'DELETE'});await refresh();renderShell();toast('Evento eliminado.')},
 'save-weather':()=>{const t=$('#weather-temp'),r=$('#weather-rain');if(!t.reportValidity()||!r.reportValidity())return;state.temperature=t.value;state.rain=r.value;state.forecast=null;state.plan=null;toast('Escenario aplicado a las próximas predicciones.');navigate('forecast')},
 'new-recipe':()=>newRecipe(),
 'new-inventory':()=>newInventory(),
 'save-recipe':async el=>{const input=$('#recipe-'+el.dataset.id);if(!input.reportValidity()||!input.value)return;await api('/recipes',{method:'PUT',body:json({producto:el.dataset.product,insumo:el.dataset.ingredient,amount:Number(input.value)/(Number(el.dataset.factor)||1)})});state.plan=null;await renderContent();toast('Medida guardada y ajustada para tu cocina.')},
 'save-stock':async el=>{const input=$('#stock-'+el.dataset.id);if(!input.reportValidity()||!input.value)return;await api('/inventory',{method:'PUT',body:json({sede:el.dataset.branch,insumo:el.dataset.ingredient,amount:Number(input.value)})});state.plan=null;toast('Inventario actualizado.')},
 'upload-inventory':()=>uploadInventory(),
 'import-inventory':async()=>{const f=$('#inventory-file').files[0];if(!f){toast('Selecciona un archivo de inventario.',true);return}const data=new FormData();data.append('file',f);const r=await api('/inventory/upload',{method:'POST',body:data});state.plan=null;$('#modal-root').innerHTML='';renderContent();toast(`${r.updated} existencias actualizadas.`)},
 'upload-back':el=>renderUpload(Number(el.dataset.step)),
 'validate-file':async()=>{document.querySelectorAll('[data-map]').forEach(el=>upload.mapping[el.dataset.map]=el.value);upload.report=await api('/uploads/validate',{method:'POST',body:json({token:upload.preview.token,mapping:upload.mapping})});renderUpload(3)},
 'import-file':async()=>{document.querySelectorAll('[data-policy]').forEach(el=>upload.policies[el.dataset.policy]=el.value);try{const r=await api('/uploads/import',{method:'POST',body:json({token:upload.preview.token,mapping:upload.mapping,policies:upload.policies})});$('#modal-root').innerHTML='';await refresh();state.view='files';renderShell();toast(`${fmt(r.imported)} registros procesados: ${fmt(r.new_rows)} nuevos, ${fmt(r.updated_rows)} actualizados.`)}catch(e){$('#import-error').innerHTML=note(e.message,'error')}},
 'account':()=>modal('Tu cuenta',`<div style="display:flex;align-items:center;gap:12px;margin-bottom:20px"><span class="avatar large">${initials(state.user.name)}</span><div><strong>${esc(state.user.name)}</strong><p class="muted small" style="margin:4px 0 0">${esc(state.user.email)}</p></div></div>${note(state.user.role==='admin'?'Administrador · Acceso a todas las sedes y configuración de recetas.':'Encargado de sede · '+state.user.sede+' · Solo puedes acceder a los datos de tu local.')}<button class="button" data-act="logout">${icon('logout')} Cerrar sesión</button>`,'',true),
 'logout':async()=>{await api('/logout',{method:'POST'});state.user=null;state.summary=null;state.branch='';state.product='';state.forecast=null;state.plan=null;$('#modal-root').innerHTML='';renderLogin()},
 'help':()=>modal('De tus datos a tu próximo servicio',`<div class="form-stack"><div><h3>1. Sube tus ventas</h3><p class="muted small">Usa Excel o CSV, mapea fecha, sede, producto y cantidad, y revisa las observaciones antes de importar.</p></div><div><h3>2. Consulta la predicción</h3><p class="muted small">Elige mañana, 7 o 30 días. Puedes simular clima y eventos. Consulta la evaluación para conocer el error histórico.</p></div><div><h3>3. Ajusta recetas e inventario</h3><p class="muted small">Introduce las cantidades reales de tu cocina. El plan calculará compras y preparación por día y sede.</p></div><div><h3>4. Lleva el plan a tu cocina</h3><p class="muted small">Descarga Excel o PDF. Revisa los rangos y las condiciones de conservación antes de ejecutar la preparación.</p></div></div>`,'<a class="button" href="/docs" target="_blank" rel="noopener">Documentación API '+icon('external')+'</a><button class="button primary" data-act="close-modal">Entendido</button>')
};
document.addEventListener('click',async e=>{const view=e.target.closest('[data-view]');if(view){navigate(view.dataset.view);return}const el=e.target.closest('[data-act]');if(!el)return;const fn=actions[el.dataset.act];if(!fn)return;const shouldDisable=['import-file','validate-file','import-inventory','save-stock','save-recipe','refresh'].includes(el.dataset.act);try{if(shouldDisable)el.disabled=true;await fn(el)}catch(error){toast(error.message,true)}finally{if(shouldDisable)el.disabled=false}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.map){upload.mapping[el.dataset.map]=el.value;return}if(el.dataset.policy){upload.policies[el.dataset.policy]=el.value;return}switch(el.dataset.change){case'branch':state.branch=el.value;renderContent();break;case'product':state.product=el.value;renderContent();break;case'day':state.day=el.value;renderContent();break;case'folder-category':state.tree=el.value;renderShell();break;case'sort-files':state.sort=el.value;$('#file-table').innerHTML=fileTable();break;case'sheet':await inspectFile(upload.file,el.value);break}}catch(error){toast(error.message,true)}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#sidebar')?.classList.add('open');$('#workspace-search')?.focus()}if(e.key==='Escape'){$('#modal-root').innerHTML='';$('#sidebar')?.classList.remove('open')}if(e.key==='Tab'&&$('#modal-root .modal')){const focus=[...document.querySelectorAll('#modal-root button:not(:disabled),#modal-root a,#modal-root input:not([hidden]),#modal-root select:not(:disabled)')];const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(state.user&&views[view]&&view!==state.view){state.view=view;renderShell()}});
(async()=>{try{state.user=await api('/me');await refresh();const view=location.hash.slice(1);if(views[view])state.view=view;renderShell()}catch{renderLogin()}})();

function costEditor(){
 if(state.user.role!=='admin')return '';
 return `<section class="panel"><div class="panel-header"><h2>Costos reales de compra</h2><span class="muted small">S/ por unidad base · vacío = pendiente</span></div><div class="table-wrap"><table><thead><tr><th>Insumo</th><th>Unidad</th><th>Costo unitario S/</th><th></th></tr></thead><tbody>${state.summary.ingredients.map((r,i)=>`<tr><td>${esc(r.name)}</td><td>${r.unit}</td><td><input type="number" class="editable" min="0" max="10000000" step="0.01" id="cost-${i}" value="${r.cost??''}" placeholder="Pendiente" aria-label="Costo de ${esc(r.name)}"></td><td><button class="button small-btn" data-act="save-cost" data-id="${i}" data-ingredient="${esc(r.name)}">${icon('save')} Guardar</button></td></tr>`).join('')}</tbody></table></div></section>`;
}

async function databaseView(){
 const info=await api('/database');
 const data=await api(`/database/tables/${encodeURIComponent(state.dbTable)}?offset=${state.dbOffset}&limit=50`);
 const total=info.tables.reduce((n,t)=>n+t.count,0);
 const cell=value=>value===null||value===undefined?'—':typeof value==='object'?JSON.stringify(value):String(value);
 return `${pageHeader('Tus datos, directamente de PostgreSQL.','Consulta las tablas que utiliza el sistema. Los cambios se realizan desde sus módulos.',`<button class="button" data-act="refresh-database">${icon('refresh')} Actualizar conexión</button>`,'Base de datos')}<div class="metrics">${metric('Estado',badge('Conectado'),'Conexión verificada con SELECT 1','shield')}${metric('Motor',esc(info.engine),esc(info.host)+':'+info.port,'building')}${metric('Base',esc(info.database),'Esquema '+esc(info.schema),'box')}${metric('Registros',fmt(total),info.tables.length+' tablas consultables','files')}</div><div class="database-tables">${info.tables.map(t=>`<button class="database-card ${t.name===state.dbTable?'active':''}" data-act="database-table" data-table="${t.name}"><span>${esc(t.label)}</span><strong>${fmt(t.count)}</strong><small>${esc(t.name)}</small></button>`).join('')}</div><section class="panel"><div class="panel-header"><div><h2>${esc(data.label)}</h2><p class="muted small" style="margin:6px 0 0">${esc(info.schema)}.${esc(data.name)} · solo lectura</p></div><span class="count">${fmt(data.total)} registros</span></div><div class="table-wrap"><table><thead><tr>${data.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${data.rows.map(row=>`<tr>${data.columns.map(c=>`<td title="${esc(cell(row[c]))}">${esc(cell(row[c]).slice(0,180))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${data.columns.length}" class="empty">Esta tabla todavía no contiene registros. Ingresa la información desde el módulo correspondiente.</td></tr>`}</tbody></table></div><div class="table-footer"><span>${data.total?data.offset+1:0}–${Math.min(data.offset+data.rows.length,data.total)} de ${data.total}</span><div class="action-row"><button class="button small-btn" data-act="database-page" data-offset="${Math.max(0,data.offset-50)}" ${data.offset===0?'disabled':''}>Anterior</button><button class="button small-btn" data-act="database-page" data-offset="${data.offset+50}" ${data.offset+50>=data.total?'disabled':''}>Siguiente</button></div></div></section>${note(`En pgAdmin: PostgreSQL 18 → Databases → ${info.database} → Schemas → ${info.schema} → Tables. Actualiza el árbol si las tablas todavía no aparecen.`)}${note('Las contraseñas y los tokens de sesión no se muestran en este visor. No se ejecutan consultas SQL introducidas por el navegador.')}${footer()}`;
}

actions['database-table']=el=>{state.dbTable=el.dataset.table;state.dbOffset=0;renderContent()};
actions['database-page']=el=>{state.dbOffset=Number(el.dataset.offset);renderContent()};
actions['refresh-database']=()=>renderContent();
actions['save-cost']=async el=>{
 const input=$('#cost-'+el.dataset.id);if(!input.reportValidity())return;
 await api('/ingredients/cost',{method:'PUT',body:json({insumo:el.dataset.ingredient,cost:input.value===''?null:Number(input.value)})});
 state.summary=await api('/summary');state.plan=null;toast('Costo de compra actualizado.');
};

actions['remove-recipe']=async el=>{await api('/recipes',{method:'DELETE',body:json({producto:el.dataset.product,insumo:el.dataset.ingredient})});state.plan=null;await renderContent();toast('Ingrediente retirado de la receta. Puedes volver a agregarlo.')};

function filteredSavings(plan){return plan.savings.rows.filter(r=>(!state.branch||r.sede===state.branch)&&(!state.day||r.fecha===state.day))}
function savingsScope(plan){const rows=filteredSavings(plan),covered=rows.filter(r=>r.diferencia!==null);return covered.length===rows.length&&rows.length?'Cobertura completa':covered.length?'Cálculo parcial':'Faltan precios o stock'}
function savingsAmount(plan){const covered=filteredSavings(plan).filter(r=>r.diferencia!==null);return covered.length?money(Math.max(0,covered.reduce((a,r)=>a+r.diferencia,0))):'Pendiente'}
function savingsTotals(plan){
 const rows=filteredSavings(plan),covered=rows.filter(r=>r.diferencia!==null),daily=new Map();
 rows.forEach(r=>{const key=r.fecha+'|'+r.sede,v=daily.get(key)||{fecha:r.fecha,sede:r.sede,baseline:0,recommended:0,net:0,covered:0,total:0};v.total++;if(r.diferencia!==null){v.baseline+=r.costo_referencia;v.recommended+=r.costo_recomendado;v.net+=r.diferencia;v.covered++}daily.set(key,v)});
 return {rows,covered,daily:[...daily.values()].sort((a,b)=>a.fecha.localeCompare(b.fecha)||a.sede.localeCompare(b.sede)),baseline:covered.reduce((a,r)=>a+r.costo_referencia,0),recommended:covered.reduce((a,r)=>a+r.costo_recomendado,0),net:covered.reduce((a,r)=>a+r.diferencia,0)};
}
async function savingsView(){
 const plan=await ensurePlan(),totals=savingsTotals(plan),s=plan.savings;
 const priced=new Set(totals.rows.filter(r=>!r.falta_precio).map(r=>r.insumo)),ingredients=new Set(totals.rows.map(r=>r.insumo));
 const dates=new Map();totals.daily.forEach(r=>dates.set(r.fecha,(dates.get(r.fecha)||0)+r.net));let cumulative=0;const progression=[...dates].map(([day,net])=>({day,net,cumulative:cumulative+=net}));
 const first=progression.find(r=>r.cumulative>0)?.day;
 const days=[...new Set(s.rows.map(r=>r.fecha))];
 return `${pageHeader('Cuánto puedes ahorrar, con un cálculo visible.','Comparamos dos planes de compra usando los mismos precios e inventario inicial.',`<button class="button" data-act="export-pdf">${icon('download')} PDF</button><button class="button primary" data-act="export-xlsx">${icon('download')} Excel con el cálculo</button>`,'Ahorro potencial')}${filters(true,false)}<div class="filters"><select class="select" data-change="day" aria-label="Filtrar día"><option value="">Todo el período</option>${days.map(d=>`<option value="${d}" ${state.day===d?'selected':''}>${shortDate(d)}</option>`).join('')}</select><span class="muted small">Las compras cubren todos los productos de la sede; el stock se calcula de forma compartida.</span></div><div class="metrics">${metric('Ahorro potencial',savingsAmount(plan),savingsScope(plan)+' · no realizado','trend','money')}${metric('Plan de referencia',totals.covered.length?money(totals.baseline):'Pendiente','Solo partidas con precio y stock','box','money')}${metric('Compra recomendada',totals.covered.length?money(totals.recommended):'Pendiente','Mismas partidas valorizadas','utensils','money')}${metric('Desde cuándo',first?shortDate(first):'—',first?'Primera fecha con saldo acumulado positivo':'No hay ahorro positivo calculable','calendar')}</div><section class="panel savings-comparison"><div><div class="eyebrow">Base de comparación</div><h2>Patrón semanal + margen de preparación</h2><p class="muted small">${esc(s.baseline)}</p><div class="margin-input"><label for="savings-margin">Margen para comparar</label><input id="savings-margin" type="number" min="0" max="100" step="1" value="${Math.round(state.margin*100)}" class="field"><span>%</span><button class="button primary" data-act="apply-margin">Recalcular ${icon('refresh')}</button></div><p class="muted small">El ${fmt(state.margin*100)} % es un supuesto editable, no un dato medido de tu operación.</p></div><div class="savings-formula"><span>Compras de referencia</span><strong>−</strong><span>Compras recomendadas</span><strong>=</strong><b>${totals.covered.length?money(totals.net):'Pendiente'}</b><small>Diferencia neta en soles para las partidas cubiertas</small></div></section>${totals.net<0?note(`La recomendación necesita ${money(-totals.net)} adicionales frente a la referencia en las partidas cubiertas. No se presenta esa diferencia como ahorro.`,'amber'):''}<section class="panel"><div class="panel-header"><h2>Ahorro estimado por día y sede</h2>${badge(savingsScope(plan),totals.covered.length===totals.rows.length?'green':'amber')}</div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Sede</th><th>Referencia S/</th><th>Recomendación S/</th><th>Diferencia neta S/</th><th>Cobertura</th></tr></thead><tbody>${totals.daily.map(r=>`<tr><td>${shortDate(r.fecha)}</td><td>${esc(r.sede)}</td><td>${r.covered?money(r.baseline):'Pendiente'}</td><td>${r.covered?money(r.recommended):'Pendiente'}</td><td><strong>${r.covered?(r.net<0?'− '+money(-r.net):money(r.net)):'Pendiente'}</strong></td><td>${r.covered}/${r.total} partidas</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Configura recetas, precios e inventario para calcular el ahorro.</td></tr>'}</tbody></table></div></section><div class="chart-grid"><section class="panel"><h2>Cobertura de precios</h2><p class="coverage-value">${priced.size}<span>/ ${ingredients.size} insumos</span></p><p class="muted small">Los insumos sin precio no se valoran como S/ 0 ni se completan con precios inventados.</p><button class="button" data-view="recipes">Configurar costos ${icon('arrow')}</button>${s.missing_prices.length?note('Faltan precios: '+s.missing_prices.join(', '),'amber'):''}</section><section class="panel"><h2>Qué respalda este importe</h2><div class="savings-fact">${icon('check')} Precios registrados en la base de datos</div><div class="savings-fact">${icon('check')} Mismo inventario inicial para ambos planes</div><div class="savings-fact">${icon('check')} Consumo diario, sin reutilizar stock</div><div class="savings-fact">${icon('check')} Las compras adicionales reducen el ahorro</div>${plan.approximate_recipes.length?note('Las cantidades de algunas recetas siguen siendo aproximadas. Ajustarlas mejora la estimación.','amber'):''}</section></div>${note(s.method)}${note(s.note,'amber')}${footer()}`;
}

let modelPlaybackTimer=null;
function stopModelPlayback(){if(modelPlaybackTimer)clearInterval(modelPlaybackTimer);modelPlaybackTimer=null;state.mlPlaying=false}
async function mlView(){
 const f=await ensureForecast(),choices=f.metrics;
 if(!choices.length)return note('Carga ventas para observar el funcionamiento del modelo.');
 let selected=choices.find(r=>JSON.stringify([r.sede,r.producto,r.turno])===state.mlSeries)||choices.find(r=>(!state.branch||r.sede===state.branch)&&(!state.product||r.producto===state.product))||choices[0];
 state.mlSeries=JSON.stringify([selected.sede,selected.producto,selected.turno]);
 const params=query();params.set('sede',selected.sede);params.set('producto',selected.producto);params.set('turno',selected.turno);
 const cacheKey=params.toString()+'|'+f.generated;
 if(state.mlCache?.key!==cacheKey){state.mlCache={key:cacheKey,data:await api('/ml/explain?'+params)}}
 const data=state.mlCache.data;
 const forecastRows=f.rows.filter(r=>r.sede===selected.sede&&r.producto===selected.producto&&r.turno===selected.turno);
 return `${pageHeader('Así se construye tu próxima predicción.','Explora los datos, las variables, el modelo entrenado y la evaluación que produce el resultado.',`<button class="button" data-view="evaluation">${icon('shield')} Ver evaluación</button><button class="button primary" data-act="ml-play">${icon(state.mlPlaying?'clock':'arrow')}${state.mlPlaying?'Pausar recorrido':'Recorrer el cálculo'}</button>`,'Cómo funciona la predicción')}<div class="filters"><div class="segmented">${[[1,'Mañana'],[7,'7 días'],[30,'30 días']].map(([n,t])=>`<button data-act="horizon" data-horizon="${n}" class="${state.horizon===n?'active':''}">${t}</button>`).join('')}</div><select class="select ml-series-select" data-change="ml-series" aria-label="Serie a explorar">${choices.map(r=>`<option value="${esc(JSON.stringify([r.sede,r.producto,r.turno]))}" ${r===selected?'selected':''}>${esc(r.sede)} · ${esc(r.producto)} · ${esc(r.turno)}</option>`).join('')}</select><select class="select" data-change="ml-day" aria-label="Fecha de predicción">${data.predictions.map((r,i)=>`<option value="${i}" ${i===(state.mlDay||0)?'selected':''}>${shortDate(r.fecha)}</option>`).join('')}</select></div><section class="ml-weather"><span>${icon('cloud')} Explora el clima de esta predicción</span><label>°C <input id="ml-temp" class="field" type="number" min="-30" max="55" step=".1" placeholder="Histórico" value="${state.temperature}"></label><label>Lluvia mm <input id="ml-rain" class="field" type="number" min="0" max="500" step=".1" placeholder="Histórico" value="${state.rain}"></label><button class="button small-btn" data-act="ml-run">Ejecutar predicción ${icon('refresh')}</button></section><div id="model-process">${renderModelLab(data,forecastRows,state)}</div>${footer()}`;
}
actions['apply-margin']=()=>{const input=$('#savings-margin');if(!input.reportValidity()||input.value==='')return;state.margin=Number(input.value)/100;state.plan=null;renderContent()};
actions['ml-stage']=el=>{stopModelPlayback();state.mlStep=Number(el.dataset.stage);renderContent()};
actions['ml-next']=()=>{stopModelPlayback();state.mlStep=Math.min(5,state.mlStep+1);renderContent()};
actions['ml-prev']=()=>{stopModelPlayback();state.mlStep=Math.max(0,state.mlStep-1);renderContent()};
actions['ml-play']=()=>{if(state.mlPlaying){stopModelPlayback();renderContent();return}state.mlPlaying=true;state.mlStep=0;renderContent();modelPlaybackTimer=setInterval(()=>{if(state.view!=='ml'||state.mlStep>=5){stopModelPlayback();if(state.view==='ml')renderContent();return}state.mlStep++;renderContent()},3200)};
actions['ml-run']=()=>{const t=$('#ml-temp'),r=$('#ml-rain');if(!t.reportValidity()||!r.reportValidity())return;stopModelPlayback();state.temperature=t.value;state.rain=r.value;state.forecast=null;state.plan=null;state.mlCache=null;state.mlStep=5;renderContent()};
document.addEventListener('change',e=>{if(e.target.dataset.change==='ml-series'){stopModelPlayback();state.mlSeries=e.target.value;state.mlDay=0;state.mlCache=null;renderContent()}if(e.target.dataset.change==='ml-day'){stopModelPlayback();state.mlDay=Number(e.target.value);renderContent()}});
